public sealed class OpenProjectTests(AppFixture fixture) : IntegrationContext(fixture)
{
    // A project is opened inside a department
    //   GIVEN (nothing)
    //   WHEN  OpenProject(name=Rewire the hall)
    //   THEN  Project Opened(name=Rewire the hall)
    [Fact]
    public async Task AProjectIsOpenedInsideADepartment()
    {
        var (_, result) = await WhenPosting(x =>
        {
            x.Post.Json(new OpenProject(SeedData.DepartmentId, "Rewire the hall"))
                .ToUrl(OpenProjectEndpoint.Route);
            x.StatusCodeShouldBeOk();
        });

        // THE ID THE API HANDED BACK, not one this test made up. projectId is terminal="generated", so the
        // handler mints it — and asserting on a variable of our own could not see a slice that echoed
        // something subtly different.
        var opened = result.ReadAsJson<OpenProjectEndpoint.Opened>()!;
        opened.ProjectId.ShouldNotBe(Guid.Empty);

        var events = await EventsFor(opened.ProjectId);
        var e = events.ShouldHaveSingleItem().ShouldBeOfType<ProjectOpened>();
        e.Name.ShouldBe("Rewire the hall");
        e.DepartmentId.ShouldBe(SeedData.DepartmentId);
    }
}
